#!/bin/zsh

val=10

add() {
    local val=$[ $1 + $2 ]
    echo "$val"
}
res=$(add 1 2)
echo "1 + 2 = $res"

# 外部 val 还是 10，不会受到影响
echo "outer val: $val."

#!/bin/zsh

array=(1 2 3 4)

process_data() {
    len=$#
    for (( i = 1; i <= $len; i++ ))
        do
            echo "param$i: $1"
            shift
        done
}

process_data ${array[*]}

#!/bin/zsh

function times2 {
    local origin_arr=($(echo "$@"))
    local new_arr=($(echo "$@"))
    local i
    for (( i = 1; i <= $#; i++ ))
    {
        # 数组元素翻倍
        new_arr[$i]=$[ ${origin_arr[$i]} * 2 ]
    }
    # 输出新数组，即返回数组
    echo ${new_arr[*]}
}

arr=(1 2 3 4 5)
# 拿到返回数组
new_arr=$(times2 ${arr[*]})
echo ${new_arr[*]}
